import os
import requests

def normalize_expense(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["MINDEE_API_KEY"]
    headers = {
        "Authorization": f"Token {api_key}",
    }
    files = {}
    data = {}
    if isinstance(payload, (bytes, bytearray)):
        files["document"] = ("document.pdf", payload)
    elif isinstance(payload, str):
        if payload.startswith("http://") or payload.startswith("https://"):
            data["document"] = payload
        else:
            files["document"] = (os.path.basename(payload) or "document.pdf", open(payload, "rb"))
    else:
        raise TypeError("payload must be bytes, file path, or URL string")
    try:
        response = requests.post(
            "https://api.mindee.net/v1/products/mindee/expense_receipts/v5/predict",
            headers=headers,
            files=files or None,
            data=data or None,
            timeout=config.get("timeout", 60),
        )
        response.raise_for_status()
    finally:
        for v in files.values():
            fobj = v[1]
            if hasattr(fobj, "close"):
                fobj.close()
    result = (lambda doc: {
        "vendor_name": (((doc.get("supplier_name") or {}).get("value")) if isinstance(doc.get("supplier_name"), dict) else doc.get("supplier_name")),
        "invoice_date": (((doc.get("date") or {}).get("value")) if isinstance(doc.get("date"), dict) else doc.get("date")),
        "invoice_number": (((doc.get("invoice_number") or {}).get("value")) if isinstance(doc.get("invoice_number"), dict) else doc.get("invoice_number")),
        "currency": (((doc.get("locale") or {}).get("currency")) if isinstance(doc.get("locale"), dict) else None),
        "subtotal": (((doc.get("total_net") or {}).get("value")) if isinstance(doc.get("total_net"), dict) else doc.get("total_net")),
        "tax": (((doc.get("total_tax") or {}).get("value")) if isinstance(doc.get("total_tax"), dict) else doc.get("total_tax")),
        "total": (((doc.get("total_amount") or {}).get("value")) if isinstance(doc.get("total_amount"), dict) else doc.get("total_amount")),
        "category": (((doc.get("category") or {}).get("value")) if isinstance(doc.get("category"), dict) else doc.get("category")),
        "payment_method": (((doc.get("payment_method") or {}).get("value")) if isinstance(doc.get("payment_method"), dict) else doc.get("payment_method")),
        "document_type": "expense_receipt",
        "line_items": [
            {
                "description": (((item.get("description") or {}).get("value")) if isinstance(item.get("description"), dict) else item.get("description")),
                "quantity": (((item.get("quantity") or {}).get("value")) if isinstance(item.get("quantity"), dict) else item.get("quantity")),
                "unit_price": (((item.get("unit_price") or {}).get("value")) if isinstance(item.get("unit_price"), dict) else item.get("unit_price")),
                "total": (((item.get("total_amount") or {}).get("value")) if isinstance(item.get("total_amount"), dict) else item.get("total_amount")),
            }
            for item in (doc.get("line_items") or [])
        ],
        "raw": response.json(),
    })(((response.json().get("document") or {}).get("inference") or {}).get("prediction") or {})
    return result
